import { useEffect, useState } from "react";
import App from "./App";
import PublicDashboard from "./PublicDashboard";
import { fetchSiteSettings, saveSiteSettings } from "./dataService";
import { DEFAULT_SITE_SETTINGS } from "./siteSettings";

const PUBLIC_LAUNCH_GATE = true;
const LAUNCH_POSTER = "data:image/jpeg;base64,";

function LaunchGate({ onAdminLogin }) {
  useEffect(() => {
    const previousTitle = document.title;
    document.title = "Coming Soon | Clean & Green Sangran";
    document.body.style.overflow = "hidden";
    return () => {
      document.title = previousTitle;
      document.body.style.overflow = "";
    };
  }, []);

  return (
    <main className="launch-gate">
      <style>{`
        * { box-sizing: border-box; }
        html, body, #root { min-height: 100%; }
        body { margin: 0; }
        .launch-gate {
          position: fixed;
          z-index: 99999;
          inset: 0;
          display: grid;
          min-height: 100dvh;
          place-items: center;
          overflow: auto;
          padding: 24px;
          color: #fff;
          background:
            radial-gradient(circle at 12% 15%, rgba(158,234,53,.22), transparent 28rem),
            radial-gradient(circle at 88% 82%, rgba(255,255,255,.12), transparent 24rem),
            linear-gradient(135deg, #032719, #075d35 55%, #043b24);
          font-family: "Manrope", "DM Sans", Arial, sans-serif;
        }
        .launch-gate__panel {
          width: min(1120px, 100%);
          text-align: center;
        }
        .launch-gate__eyebrow {
          display: inline-flex;
          margin-bottom: 13px;
          padding: 7px 14px;
          border: 1px solid rgba(158,234,53,.5);
          border-radius: 999px;
          color: #b8f35d;
          background: rgba(0,0,0,.18);
          font-size: 11px;
          font-weight: 900;
          letter-spacing: 2px;
        }
        .launch-gate h1 {
          margin: 0 0 18px;
          font-size: clamp(32px, 6vw, 68px);
          line-height: 1;
          letter-spacing: -2px;
        }
        .launch-gate__poster {
          display: block;
          width: 100%;
          max-height: min(69vh, 690px);
          object-fit: contain;
          border: 3px solid rgba(184,243,93,.72);
          border-radius: 22px;
          background: #eef9ef;
          box-shadow: 0 28px 90px rgba(0,0,0,.38);
        }
        .launch-gate__date {
          margin: 15px 0 0;
          color: #dff5d4;
          font-size: clamp(13px, 2vw, 18px);
          font-weight: 800;
          letter-spacing: .5px;
        }
        .launch-gate__admin {
          position: fixed;
          right: 14px;
          bottom: 14px;
          min-height: 40px;
          padding: 9px 15px;
          color: #eaffdf;
          border: 1px solid rgba(255,255,255,.28);
          border-radius: 999px;
          background: rgba(2,31,18,.82);
          font-size: 11px;
          font-weight: 800;
          cursor: pointer;
          backdrop-filter: blur(12px);
        }
        .launch-gate__admin:hover {
          color: #07331e;
          border-color: #b8f35d;
          background: #b8f35d;
        }
        @media (max-width: 600px) {
          .launch-gate { padding: 14px 12px 72px; }
          .launch-gate__eyebrow { margin-bottom: 9px; font-size: 9px; letter-spacing: 1.3px; }
          .launch-gate h1 { margin-bottom: 13px; font-size: 35px; letter-spacing: -1px; }
          .launch-gate__poster { max-height: 60vh; border-width: 2px; border-radius: 14px; }
          .launch-gate__date { margin-top: 11px; font-size: 12px; }
          .launch-gate__admin { right: 10px; bottom: 10px; min-height: 38px; padding: 8px 13px; font-size: 10px; }
        }
      `}</style>

      <section className="launch-gate__panel">
        <span className="launch-gate__eyebrow">CLEAN &amp; GREEN SANGRAN</span>
        <h1>COMING SOON</h1>
        <img
          className="launch-gate__poster"
          src={LAUNCH_POSTER}
          alt="Clean and Green Sangran official website launch on 14 August"
        />
        <p className="launch-gate__date">Official Website Launch • 14 August</p>
      </section>

      <button className="launch-gate__admin" type="button" onClick={onAdminLogin}>
        🔒 Admin Login
      </button>
    </main>
  );
}

function Root() {
  const [adminMode, setAdminMode] = useState(false);
  const [siteSettings, setSiteSettings] = useState(DEFAULT_SITE_SETTINGS);
  const [savingSettings, setSavingSettings] = useState(false);

  const loadSettings = async () => {
    try { setSiteSettings(await fetchSiteSettings()); } catch (error) { console.warn("Website settings not ready", error); }
  };
  useEffect(() => { loadSettings(); }, []);

  const publishSettings = async (nextSettings) => {
    setSavingSettings(true);
    try { setSiteSettings(await saveSiteSettings(nextSettings)); }
    finally { setSavingSettings(false); }
  };

  if (!adminMode && PUBLIC_LAUNCH_GATE) {
    return <LaunchGate onAdminLogin={() => setAdminMode(true)} />;
  }

  if (!adminMode) {
    return <PublicDashboard onAdminLogin={() => setAdminMode(true)} siteSettings={siteSettings} onSettingsChanged={loadSettings} />;
  }

  return (
    <>
      <button
        type="button"
        onClick={() => setAdminMode(false)}
        style={{
          position: "fixed",
          right: "18px",
          bottom: "18px",
          zIndex: 1000,
          padding: "11px 16px",
          color: "white",
          fontWeight: 700,
          background: "#2563eb",
          border: 0,
          borderRadius: "10px",
          boxShadow: "0 8px 22px rgba(37, 99, 235, 0.3)",
          cursor: "pointer",
        }}
      >
        View Public Website
      </button>
      <App siteSettings={siteSettings} onSaveSiteSettings={publishSettings} savingSiteSettings={savingSettings} />
    </>
  );
}

export default Root;

